from datetime import datetime

from .adapters import FmSoapAdapter


class Service:
    name: str

    def __init__(self, web_url, username, password):
        self.soap_api = FmSoapAdapter(self.name, web_url, username, password)


class AlarmDelegateService(Service):
    name = 'alarmDelegateService'

    def acknowledge_alarms_by_keys(self, alarm_keys, ack_user_id, ack_time=None):
        """
        Acknowledge the requested alarms.

        :param int|list alarm_keys: Alarm keys for which acknowledge operation has to be performed.
        :param string ack_user_id: User who has triggered the acknowledge operation.
        :param datetime ack_time: UTC time when the alarm is acknowledged.
            If `None` then the time when alarm is acknowledged in NetAct system is used.
        :return: Alarm keys for which the acknowledge operation failed.
        :rtype: list(dict)
        """
        ack_time = self._convert_date_time(ack_time) if ack_time else None
        return self.soap_api.service.acknowledgeAlarmsByKeys(
            alarmKeys=alarm_keys, ackUserId=ack_user_id, ackTime=ack_time)

    def unacknowledge_alarms_by_keys(self, alarm_keys, unack_user_id, unack_time=None):
        """
        Unacknowledge the requested alarms.

        :param int|list alarm_keys: Alarm keys for which unacknowledge operation has to be performed.
        :param string unack_user_id: User who has triggered the unacknowledge operation.
        :param datetime unack_time: UTC time when the alarm is unacknowledged.
            If `None` then the time when alarm is unacknowledged in NetAct system is used.
        :return: Alarm keys for which the unacknowledge operation failed.
        :rtype: list(dict)
        """
        unack_time = self._convert_date_time(unack_time) if unack_time else None
        return self.soap_api.service.unAcknowledgeAlarmsByKeys(
            alarmKeys=alarm_keys, unAckUserId=unack_user_id, unackTime=unack_time)

    def clear_alarms_by_keys(self, alarm_keys, clear_user_id, clear_time=None):
        """
        Clear the requested alarms.

        :param int|list alarm_keys: Alarm keys for which clear operation has to be performed.
        :param string clear_user_id: User who has triggered the clear operation.
        :param datetime clear_time: UTC time when the alarm is cleared.
            If `None` then the time when alarm is cleared in NetAct system is used.
        :return: Alarm keys for which the clear operation failed.
        :rtype: list(dict)
        """
        clear_time = self._convert_date_time(clear_time) if clear_time else None
        return self.soap_api.service.clearAlarmsByKeys(
            alarmKeys=alarm_keys, clearUserId=clear_user_id, clearTime=clear_time)

    def nsn_alarm_key(self, alarm_id):
        """
        :param int alarm_id: Alarm id
        :return: alarmKeys
        :rtype: list(dict)
        """
        return self.soap_api.type_factory.nsnAlarmKey(alarmId=alarm_id)

    @staticmethod
    def _convert_date_time(date_time):
        """
        Convert datetime to format required by ackTime/unAckTime/clearTime:
        `YYYY-MM-DDTHH:MM:SS.sss+/-HH:MM`, e.g. `2022-02-22T22:22:22.000+00:00`

        :param datetime date_time: UTC datetime.
        :return: Datetime in format required by ackTime/unAckTime
        :rtype: string
        """
        if isinstance(date_time, datetime):
            date_time = date_time.replace(microsecond=0).isoformat(sep='T')
            ms = '000'
            tz = '+00:00'
            return f'{date_time}.{ms}{tz}'
        else:
            exc_msg = (f'Parameter with _time postfix must be datetime type, '
                       f'not {type(date_time)} type')
            raise TypeError(exc_msg)
